POST /services/data/v58.0/composite/sobjects/ HTTP/1.1
Content-Type: application/json

{
  "records": [
    {
      "attributes": {
        "type": "Contact",
        "referenceId": "contact1"
      },
      "FirstName": "Maya",
      "LastName": "Chen",
      "Email": "maya.chen@example.com",
      "AccountId": "0015g00000TrAd3AAB"
    },
    {
      "attributes": {
        "type": "Contact",
        "referenceId": "contact2"
      },
      "FirstName": "Luis",
      "LastName": "Ortega",
      "Email": "luis.ortega@example.com",
      "AccountId": "0015g00000TrAd3AAB"
    },
    {
      "attributes": {
        "type": "Contact",
        "referenceId": "contact3"
      },
      "FirstName": "Priya",
      "LastName": "Nair",
      "Email": "priya.nair@example.com",
      "AccountId": "0015g00000TrAd3AAB"
    }
  ],
  "allOrNone": true
}
###
PATCH /services/data/v58.0/composite/sobjects/ HTTP/1.1
Content-Type: application/json

{
  "records": [
    {
      "attributes": {
        "type": "Account",
        "referenceId": "account1"
      },
      "Id": "0015g00000TrAd3AAB",
      "Rating": "Hot"
    },
    {
      "attributes": {
        "type": "Opportunity",
        "referenceId": "opp1"
      },
      "Id": "0065g00000TrAd9AAB",
      "NextStep": "Send pricing"
    }
  ],
  "allOrNone": false
}
```

